-- Supabase Postgres schema. Inventory starts empty; original categories retained.
create table public.categories (id bigint generated by default as identity primary key,parent_id bigint references public.categories(id),name text not null check(length(trim(name)) between 1 and 100),is_archived boolean not null default false,created_at timestamptz not null default now());
create index categories_parent_idx on public.categories(parent_id);
create table public.items (id bigint generated by default as identity primary key,category_id bigint not null references public.categories(id),name text not null check(length(trim(name)) between 1 and 150),quantity numeric(10,2) not null default 0 check(quantity>=0),unit text not null default 'pcs',reorder_level numeric(10,2) not null default 0 check(reorder_level>=0),quantity_needed numeric(10,2) check(quantity_needed>=0),buy_location text,supplier_contact text,photo_path text,flagged_for_purchase boolean not null default false,is_archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index items_category_idx on public.items(category_id);
create table public.stock_logs (id bigint generated by default as identity primary key,item_id bigint references public.items(id) on delete set null,item_name text not null,staff_name text not null,change_amount numeric(10,2) not null,resulting_quantity numeric(10,2) not null,actor_id uuid references auth.users(id) on delete set null,logged_at timestamptz not null default now());
create index stock_logs_item_idx on public.stock_logs(item_id);
create index stock_logs_actor_idx on public.stock_logs(actor_id);
create index stock_logs_time_idx on public.stock_logs(logged_at desc);
create table public.extra_buy_items (id bigint generated by default as identity primary key,name text not null check(length(trim(name)) between 1 and 150),quantity_needed numeric(10,2) check(quantity_needed>=0),unit text not null default 'pcs',buy_location text,supplier_contact text,is_bought boolean not null default false,added_by text,created_at timestamptz not null default now());
create table public.purchase_log (id bigint generated by default as identity primary key,item_id bigint references public.items(id) on delete set null,extra_item_id bigint references public.extra_buy_items(id) on delete set null,item_name text not null,quantity_needed numeric(10,2),logged_by text not null,actor_id uuid references auth.users(id) on delete set null,logged_at timestamptz not null default now());
create index purchase_log_item_idx on public.purchase_log(item_id);
create index purchase_log_extra_idx on public.purchase_log(extra_item_id);
create index purchase_log_actor_idx on public.purchase_log(actor_id);
create index purchase_log_time_idx on public.purchase_log(logged_at desc);
-- All table access is restricted to the verified Edge Function.
alter table public.categories enable row level security;
alter table public.items enable row level security;
alter table public.stock_logs enable row level security;
alter table public.extra_buy_items enable row level security;
alter table public.purchase_log enable row level security;
revoke all on public.categories,public.items,public.stock_logs,public.extra_buy_items,public.purchase_log from anon,authenticated;
grant all on public.categories,public.items,public.stock_logs,public.extra_buy_items,public.purchase_log to service_role;
grant usage,select on all sequences in schema public to service_role;
create function public.adjust_stock(p_item_id bigint,p_change numeric,p_staff text,p_actor uuid)
returns numeric language plpgsql security invoker set search_path = public as $$
declare v_item public.items; v_quantity numeric;
begin
 if p_change=0 or p_change is null or length(trim(p_staff))=0 then raise exception 'Enter an amount and your name'; end if;
 select * into v_item from public.items where id=p_item_id and not is_archived for update;
 if not found then raise exception 'Item not found or archived'; end if;
 v_quantity:=v_item.quantity+p_change;
 if v_quantity<0 then raise exception 'Cannot remove more than the available stock'; end if;
 update public.items set quantity=v_quantity,updated_at=now() where id=p_item_id;
 insert into public.stock_logs(item_id,item_name,staff_name,change_amount,resulting_quantity,actor_id) values(p_item_id,v_item.name,p_staff,p_change,v_quantity,p_actor);
 return v_quantity;
end $$;
revoke all on function public.adjust_stock(bigint,numeric,text,uuid) from public,anon,authenticated;
grant execute on function public.adjust_stock(bigint,numeric,text,uuid) to service_role;
create function public.record_purchase(p_id bigint,p_extra boolean,p_quantity numeric,p_name text,p_actor uuid)
returns void language plpgsql security invoker set search_path = public as $$
declare v_name text;
begin
 if length(trim(p_name))=0 or p_quantity<0 then raise exception 'Enter your name and a valid quantity'; end if;
 if p_extra then select name into v_name from public.extra_buy_items where id=p_id and not is_bought for update;
 else select name into v_name from public.items where id=p_id and not is_archived for update; end if;
 if not found then raise exception 'Item not found or already purchased'; end if;
 insert into public.purchase_log(item_id,extra_item_id,item_name,quantity_needed,logged_by,actor_id) values(case when not p_extra then p_id end,case when p_extra then p_id end,v_name,p_quantity,p_name,p_actor);
 if p_extra then update public.extra_buy_items set is_bought=true where id=p_id; end if;
end $$;
revoke all on function public.record_purchase(bigint,boolean,numeric,text,uuid) from public,anon,authenticated;
grant execute on function public.record_purchase(bigint,boolean,numeric,text,uuid) to service_role;
-- PIN hashes stay in a non-exposed schema. Rate limits persist across function instances.
create schema if not exists private;
create table private.cafe_access (role text primary key check(role in ('admin','staff')),pin_hash text not null,email text not null);
create table private.pin_attempts (key text primary key,window_start timestamptz not null,attempts integer not null);
alter table private.cafe_access enable row level security;
alter table private.pin_attempts enable row level security;
grant usage on schema private to service_role;
grant all on private.cafe_access,private.pin_attempts to service_role;
create function public.pin_access(p_key text,p_pin text) returns text language plpgsql security invoker set search_path=public,private,extensions as $$
declare n integer; g integer; v_email text;
begin
 insert into private.pin_attempts values(p_key,now(),1) on conflict(key) do update set attempts=case when private.pin_attempts.window_start<now()-interval '15 minutes' then 1 else private.pin_attempts.attempts+1 end,window_start=case when private.pin_attempts.window_start<now()-interval '15 minutes' then now() else private.pin_attempts.window_start end returning attempts into n;
 insert into private.pin_attempts values('global',now(),1) on conflict(key) do update set attempts=case when private.pin_attempts.window_start<now()-interval '15 minutes' then 1 else private.pin_attempts.attempts+1 end,window_start=case when private.pin_attempts.window_start<now()-interval '15 minutes' then now() else private.pin_attempts.window_start end returning attempts into g;
 if n>5 or g>100 then return 'RATE_LIMIT'; end if;
 select email into v_email from private.cafe_access where pin_hash=extensions.crypt(p_pin,pin_hash);
 if v_email is not null then delete from private.pin_attempts where key=p_key; end if;
 delete from private.pin_attempts where window_start<now()-interval '1 day';
 return v_email;
end $$;
revoke all on function public.pin_access(text,text) from public,anon,authenticated;
grant execute on function public.pin_access(text,text) to service_role;
